mapper.select:
SELECT CAST(l.user_id AS TEXT) AS dimension_key, u.username, u.name AS display_name, u.remark, COALESCE(SUM(l.tokens_input), 0) AS tokens_input, COALESCE(SUM(l.tokens_output), 0) AS tokens_output, COALESCE(SUM(l.cost_yuan), 0) AS cost_yuan, COALESCE(SUM(l.points_consumed), 0) AS points, COUNT(*) AS call_count FROM llm_usage_logs l LEFT JOIN users u ON u.id = l.user_id
l.created_at >= #{from} AND l.created_at < #{to}
GROUP BY l.user_id, u.username, u.name, u.remark ORDER BY points DESC NULLS LAST LIMIT #{limit}

SELECT 
FROM llm_usage_logs

    created_at >= #{from}
    AND created_at < #{to}

GROUP BY model
ORDER BY points DESC NULLS LAST
LIMIT #{limit}

SELECT 
FROM llm_usage_logs

    created_at >= #{from}
    AND created_at < #{to}

GROUP BY kind
ORDER BY points DESC NULLS LAST

SELECT to_char(created_at, 'YYYY-MM-DD') AS day, COALESCE(SUM(cost_yuan), 0) AS cost_yuan, COALESCE(SUM(points_consumed), 0) AS points, COUNT(*) AS call_count FROM llm_usage_logs
created_at >= #{from} AND created_at < #{to}
GROUP BY day ORDER BY day ASC

SELECT
    l.created_at,
    l.model,
    l.kind,
    l.points_consumed,
    l.status,
    l.project_group_id,
    pg.name AS project_group_name
FROM llm_usage_logs l
LEFT JOIN project_groups pg ON pg.id = l.project_group_id
WHERE l.user_id = #{userId}
AND l.project_group_id = #{projectGroupId}
AND l.created_at >= #{from}
AND l.created_at < #{to}
ORDER BY l.created_at DESC
LIMIT #{limit}
